  var v3 = (x, y, z) => ({ x, y, z });
  var v3add = (a, b) => ({ x: a.x + b.x, y: a.y + b.y, z: a.z + b.z });
  var v3sub = (a, b) => ({ x: a.x - b.x, y: a.y - b.y, z: a.z - b.z });
  var v3scale = (a, s) => ({ x: a.x * s, y: a.y * s, z: a.z * s });
  var v3dot = (a, b) => a.x * b.x + a.y * b.y + a.z * b.z;
  var v3len = (a) => Math.sqrt(a.x * a.x + a.y * a.y + a.z * a.z);
  var v3norm = (a) => {
    const l = v3len(a) || 1;
    return { x: a.x / l, y: a.y / l, z: a.z / l };
  };
  var v3cross = (a, b) => ({
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x
  });
  function rotateXYZ(p, rx, ry, rz) {
    const cx = Math.cos(rx), sx = Math.sin(rx);
    const cy = Math.cos(ry), sy = Math.sin(ry);
    const cz = Math.cos(rz), sz = Math.sin(rz);
    const y1 = p.y * cx - p.z * sx;
    const z1 = p.y * sx + p.z * cx;
    const x2 = p.x * cy + z1 * sy;
    const z2 = -p.x * sy + z1 * cy;
    const x3 = x2 * cz - y1 * sz;
    const y3 = x2 * sz + y1 * cz;
    return { x: x3, y: y3, z: z2 };
  }
